def score(log_expression, reference, mss=None):
    """Score one profile using an explicit frozen reference; mss is True/False/None."""
    if reference not in REF: raise ValueError('reference must be TCGA or GSE39582')
    if mss is not None and type(mss) is not bool: raise ValueError('mss must be bool or None')
    missing=[g for g in GENES if g not in log_expression]
    if missing: raise ValueError('Missing required genes: '+','.join(missing))
    values=[float(log_expression[g]) for g in GENES]
    if not all(isfinite(v) for v in values): raise ValueError('Non-finite expression')
    gm,gs,mm,ms,dm,ds,apm_cut,tgfb_cut=REF[reference]
    z=dict(zip(GENES,((v-a)/b for v,a,b in zip(values,gm,gs))))
    modules={k:sum(z[g]*w for g,w in weights) for k,weights in MODULES}
    fv=[(modules[k]-a)/b for k,a,b in zip(FEATURES,CLASS_MODULE_MEAN,CLASS_MODULE_SD)]
    logit=INTERCEPT+sum(w*v for w,v in zip(COEF,fv))
    e=exp(-abs(logit)); probability=1/(1+e) if logit>=0 else e/(1+e)
    mz={k:(modules[k]-a)/b for k,a,b in zip(FEATURES,mm,ms)}
    raw=(modules['CXCR3_Trafficking']-modules['TGFB_CAF_Barrier'],
         modules['APM_TAP_Score'],-modules['VEGF_TOX_Exhaustion'],modules['S_triad'],
         -(mz['KRAS_IRF2_CXCL3_Axis']+mz['SPP1_Core_Barrier'])/2,logit)
    dz=tuple((v-a)/b for v,a,b in zip(raw,dm,ds))
    apm=all(v>=cut for v,cut in zip((raw[1],z['TAP1'],z['TAP2'],z['PSMB8']),apm_cut))
    aacr=z['FAP']<0 and z['CXCL10']>0; hot=probability>=.5
    gates={'CMS1_Like_MSS':hot,'Trafficking_Permissive_Primed_MSS':hot and raw[0]>0 and apm,
           'AACR_A065_Positive_MSS':aacr,'AACR_A065_APM_Intact_MSS':aacr and apm,
           'D1_Plus_D2_Permissive_MSS':raw[0]>0 and raw[1]>0,
           'v1_lowTGFB_gate_comparison':hot and modules['TGFB_CAF_Barrier']<tgfb_cut and apm}
    gates={k:(False if mss is False else v if mss is True or not v else None) for k,v in gates.items()}
    return dict(modules,**dict(zip(DOMAINS,raw)),classifier_score=probability,classifier_logit=logit,
                D1_D2_Vaccine_Effector_Index=sum(dz[:2])/2,
                D1_D2_D3_D4_Immune_Competence_Index=sum(dz[:4])/4,
                STC1010_Readiness_Score=sum(dz)/6,APM_intact=apm,**gates)
